<style>
  body {
    margin: 0;
    padding: 0;
    background: #111;
    font-family: 'Courier New', Courier, monospace;
  }
  .poster {
    max-width: 1000px;
    margin: 20px auto;
    background: #f2ecd8;
    border: 6px solid #111;
    padding: 6px;
  }
  .inner {
    background: #f6d80a;
    padding: 0 0 20px 0;
  }
  .headline {
    background: #f6d80a;
